mapper.update:
UPDATE TBL_QPS_INCIDENT
   SET USE_YN = 'N', UPD_USER = #{updUser}
 WHERE INCID_SEQ = #{incidSeq}
   AND HOSP_CD   = #{hospCd}

mapper.select:
SELECT SUBSTRING(OBS_DT, 5, 2) AS mm,
       SUM(PASS_CNT)           AS numer,
       SUM(OBS_CNT)            AS denom
  FROM TBL_QPS_MONITOR
 WHERE HOSP_CD = #{hospCd}
   AND INDI_CD = #{indiCd}
   AND USE_YN  = 'Y'
   AND SUBSTRING(OBS_DT, 1, 4) = #{inYear}
 GROUP BY SUBSTRING(OBS_DT, 5, 2)

SELECT CENSUS_SEQ AS censusseq, CENSUS_GB AS censusgb, IN_YEAR AS inyear,
       M01 AS m01, M02 AS m02, M03 AS m03, M04 AS m04, M05 AS m05, M06 AS m06,
       M07 AS m07, M08 AS m08, M09 AS m09, M10 AS m10, M11 AS m11, M12 AS m12
  FROM TBL_QPS_CENSUS
 WHERE HOSP_CD   = #{hospCd}
   AND CENSUS_GB = #{censusGb}
   AND IN_YEAR   = #{inYear}
   AND USE_YN    = 'Y'
 LIMIT 1


SELECT SUBSTRING(OCCUR_DT, 5, 2) AS mm,
       COUNT(*)                  AS cnt
  FROM TBL_QPS_INCIDENT
 WHERE HOSP_CD  = #{hospCd}
   AND INCID_GB = #{incidGb}
   AND USE_YN   = 'Y'
   AND SUBSTRING(OCCUR_DT, 1, 4) = #{inYear}


	AND CAST(REPLACE(IFNULL(LEVEL_CD,'LV0'),'LV','') AS UNSIGNED) >= #{minLevel}

GROUP BY SUBSTRING(OCCUR_DT, 5, 2)

SELECT RPT_SEQ AS rptseq, TITLE AS title,
       ANALYSIS_TXT AS analysistxt, PLAN_TXT AS plantxt,
       ACT1_TXT AS act1txt, ACT2_TXT AS act2txt, ACT3_TXT AS act3txt, ACT4_TXT AS act4txt,
       STATUS AS status,
       SIGN1_USER AS sign1user, DATE_FORMAT(SIGN1_DTTM,'%Y-%m-%d %H:%i') AS sign1dttm,
       SIGN2_USER AS sign2user, DATE_FORMAT(SIGN2_DTTM,'%Y-%m-%d %H:%i') AS sign2dttm,
       DATE_FORMAT(UPD_DTTM,'%Y-%m-%d %H:%i') AS upddttm
  FROM TBL_QPS_REPORT
 WHERE HOSP_CD = #{hospCd}
   AND INDI_CD = #{indiCd}
   AND PRD_GB  = #{prdGb}
   AND PRD_KEY = #{prdKey}
 LIMIT 1
